window.OPUS_PAGES["038"] = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>HYPERBRICK — Synthwave Breakout Arcade</title>\n<meta name=\"description\" content=\"HYPERBRICK is a playable synthwave Breakout cabinet: neon bricks that shatter into particles, combos with rising synth blips, multi-ball, wide paddle, laser and slow-mo power-ups, five hand-built stages and an endless mode.\">\n<meta name=\"theme-color\" content=\"#12002b\">\n<style>\n:root{\n  --bg:#12002b;\n  --pink:#ff2e97;\n  --orange:#ff9e00;\n  --yellow:#fff200;\n  --cyan:#00f5d4;\n  --blue:#00bbf9;\n  --violet:#9b5de5;\n  --ink:#f6eaff;\n  --dim:#b69ad8;\n  --display:\"Avenir Next Condensed\",\"Futura Condensed\",\"Arial Narrow\",\"Nimbus Sans Narrow\",\"Helvetica Neue\",Arial,sans-serif;\n  --wide:\"Avenir Next\",\"Futura\",\"Segoe UI\",\"Nimbus Sans\",\"Helvetica Neue\",Arial,sans-serif;\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;height:100%;overflow:hidden}\nbody{background:var(--bg);color:var(--ink);font-family:var(--wide);touch-action:none;-webkit-user-select:none;user-select:none;-webkit-tap-highlight-color:transparent}\nbutton{font:inherit;color:inherit}\n\n/* ------------ the world behind the cabinet ------------ */\n.world{position:fixed;inset:0;overflow:hidden;pointer-events:none;\n  background:linear-gradient(180deg,#0b001c 0%,#12002b 38%,#2a0747 58%,#12002b 58.2%,#12002b 100%)}\n.world .stars{position:absolute;inset:0 0 42% 0;background:\n  radial-gradient(1px 1px at 12% 18%,#fff 60%,transparent),radial-gradient(1px 1px at 26% 42%,#ffd6f0 60%,transparent),\n  radial-gradient(1.4px 1.4px at 41% 12%,#fff 60%,transparent),radial-gradient(1px 1px at 58% 30%,#c9f7ff 60%,transparent),\n  radial-gradient(1px 1px at 73% 9%,#fff 60%,transparent),radial-gradient(1.3px 1.3px at 86% 36%,#ffe9a8 60%,transparent),\n  radial-gradient(1px 1px at 93% 16%,#fff 60%,transparent),radial-gradient(1px 1px at 5% 48%,#fff 60%,transparent),\n  radial-gradient(1px 1px at 33% 26%,#fff 60%,transparent),radial-gradient(1px 1px at 66% 50%,#ffc2e4 60%,transparent);opacity:.8}\n.world .bigsun{position:absolute;left:50%;top:58%;width:min(78vw,860px);aspect-ratio:1;transform:translate(-50%,-50%);border-radius:50%;\n  background:linear-gradient(180deg,#fff27a 0%,#ffb13b 32%,#ff4f8b 62%,#b0249a 100%);opacity:.22;\n  -webkit-mask:linear-gradient(180deg,#000 0 52%,transparent 52% 55%,#000 55% 61%,transparent 61% 65%,#000 65% 70%,transparent 70% 75%,#000 75% 79%,transparent 79% 85%,#000 85% 88%,transparent 88% 100%);\n          mask:linear-gradient(180deg,#000 0 52%,transparent 52% 55%,#000 55% 61%,transparent 61% 65%,#000 65% 70%,transparent 70% 75%,#000 75% 79%,transparent 79% 85%,#000 85% 88%,transparent 88% 100%)}\n.world .glow{position:absolute;left:50%;top:58%;width:140vw;height:60vh;transform:translate(-50%,-50%);background:radial-gradient(closest-side,rgba(255,46,151,.35),rgba(155,93,229,.12) 55%,transparent)}\n.world .floor{position:absolute;left:-50%;right:-50%;top:58%;height:70%;perspective:340px;overflow:hidden}\n.world .plane{position:absolute;left:0;right:0;top:0;height:220%;transform-origin:50% 0;transform:rotateX(64deg);\n  background:\n    repeating-linear-gradient(90deg,rgba(255,46,151,.55) 0 2px,transparent 2px 64px),\n    repeating-linear-gradient(180deg,rgba(255,46,151,.55) 0 2px,transparent 2px 64px);\n  animation:floor 1.6s linear infinite}\n@keyframes floor{from{background-position:0 0,0 0}to{background-position:0 0,0 64px}}\n.world .horizon{position:absolute;left:0;right:0;top:58%;height:2px;background:linear-gradient(90deg,transparent,#ff2e97 20%,#ffd1ea 50%,#ff2e97 80%,transparent);box-shadow:0 0 18px 4px rgba(255,46,151,.55)}\n.world .fade{position:absolute;inset:58% 0 0 0;background:linear-gradient(180deg,rgba(18,0,43,.1),rgba(18,0,43,.85) 85%)}\n\n/* ------------ cabinet ------------ */\n.cabinet{position:relative;z-index:1;height:100%;height:100dvh;display:flex;flex-direction:column;align-items:center;padding:14px 18px 10px}\n.marquee{position:relative;flex:0 0 auto;display:flex;align-items:center;justify-content:center;gap:18px;width:min(100%,1180px);padding:6px 24px 8px;border-radius:14px 14px 6px 6px;\n  background:linear-gradient(180deg,rgba(40,6,74,.9),rgba(18,0,43,.9));box-shadow:inset 0 0 0 1px rgba(255,46,151,.5),inset 0 0 30px rgba(255,46,151,.18),0 0 28px rgba(255,46,151,.22)}\n.marquee::before,.marquee::after{content:\"\";width:clamp(20px,9vw,150px);height:2px;background:linear-gradient(90deg,transparent,var(--cyan));box-shadow:0 0 8px var(--cyan)}\n.marquee::after{background:linear-gradient(90deg,var(--cyan),transparent)}\n.logo{position:relative;margin:0;font-family:var(--display);font-style:italic;font-weight:900;font-size:clamp(30px,5.2vw,58px);letter-spacing:.04em;line-height:1;text-transform:uppercase;\n  background:linear-gradient(180deg,#ffffff 0%,#ffffff 36%,#ffd0ec 48%,#ff2e97 60%,#ff9e00 78%,#fff200 100%);-webkit-background-clip:text;background-clip:text;color:transparent;\n  -webkit-text-stroke:1px rgba(255,255,255,.35);filter:drop-shadow(0 0 6px rgba(255,46,151,.9)) drop-shadow(0 0 22px rgba(255,46,151,.45));transform:skewX(-6deg)}\n.logo::after{content:attr(data-text);position:absolute;left:3px;top:3px;z-index:-1;color:transparent;-webkit-text-stroke:1.5px var(--cyan);background:none;filter:drop-shadow(0 0 6px var(--cyan))}\n.tagline{margin:0;font-family:var(--display);font-style:italic;font-weight:700;font-size:13px;letter-spacing:.3em;color:var(--cyan);text-shadow:0 0 8px rgba(0,245,212,.7);white-space:nowrap}\n\n.deck{flex:1 1 auto;min-height:0;width:min(100%,1180px);display:flex;align-items:stretch;justify-content:center;gap:clamp(14px,2.6vw,40px);padding-top:12px}\n.slot{position:relative;flex:1 1 auto;min-width:0;min-height:0}\n.bezel{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);border-radius:26px;padding:var(--pad,20px);\n  background:\n    radial-gradient(120% 60% at 50% 0%,rgba(255,46,151,.16),transparent 60%),\n    linear-gradient(160deg,#2a0b4d 0%,#170433 45%,#0c011d 100%);\n  box-shadow:0 0 0 2px #3c1070,0 0 0 4px rgba(255,46,151,.85),0 0 26px 4px rgba(255,46,151,.45),0 30px 80px rgba(0,0,0,.6),inset 0 2px 0 rgba(255,255,255,.14),inset 0 -8px 24px rgba(0,0,0,.5)}\n.bezel::before{content:\"\";position:absolute;inset:8px;border-radius:20px;box-shadow:inset 0 0 0 1px rgba(0,245,212,.55),0 0 10px rgba(0,245,212,.35);pointer-events:none}\n.screw{position:absolute;width:9px;height:9px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#d9c9f2,#6e5a96 60%,#2a1a44);box-shadow:0 1px 1px rgba(0,0,0,.6)}\n.screw::after{content:\"\";position:absolute;left:1px;right:1px;top:4px;height:1px;background:#2a1a44;transform:rotate(35deg)}\n.screw.s1{left:10px;top:10px}.screw.s2{right:10px;top:10px}.screw.s3{left:10px;bottom:10px}.screw.s4{right:10px;bottom:10px}\n.screen{position:relative;overflow:hidden;border-radius:14px;background:#12002b;box-shadow:0 0 0 2px #05000c,inset 0 0 40px rgba(0,0,0,.8)}\n#game{display:block;touch-action:none}\n#game:focus-visible{outline:2px solid rgba(255,242,0,.55);outline-offset:-2px}\n.scan{position:absolute;inset:0;pointer-events:none;border-radius:14px;\n  background:repeating-linear-gradient(180deg,rgba(0,0,0,.2) 0 1px,transparent 1px 3px),radial-gradient(120% 90% at 50% 50%,transparent 60%,rgba(0,0,0,.55) 100%);\n  box-shadow:inset 0 0 0 1px rgba(255,255,255,.05),inset 0 0 60px rgba(0,0,0,.45)}\n.glare{position:absolute;inset:0;pointer-events:none;border-radius:14px;background:linear-gradient(125deg,rgba(255,255,255,.07) 0%,rgba(255,255,255,0) 32%)}\n\n.hud-top{display:none}\n\n/* ------------ side panels ------------ */\n.panel{flex:0 0 clamp(190px,17vw,236px);display:flex;flex-direction:column;gap:12px;justify-content:center;min-height:0}\n.card{position:relative;padding:12px 14px 13px;border-radius:12px;background:linear-gradient(180deg,rgba(40,8,78,.78),rgba(16,0,38,.78));box-shadow:inset 0 0 0 1px rgba(155,93,229,.45),0 10px 30px rgba(0,0,0,.35)}\n.card h2{margin:0 0 4px;font-family:var(--display);font-style:italic;font-weight:800;font-size:12px;letter-spacing:.28em;color:var(--dim);text-transform:uppercase}\n.big{margin:0;font-family:var(--display);font-style:italic;font-weight:900;font-size:clamp(28px,2.6vw,38px);line-height:1.05;letter-spacing:.04em;font-variant-numeric:tabular-nums;color:#fff;text-shadow:0 0 6px var(--c,var(--pink)),0 0 18px var(--c,var(--pink))}\n.big.cy{--c:var(--cyan)}.big.yl{--c:var(--orange)}.big.vi{--c:var(--violet)}\n.sub{margin:2px 0 0;font-family:var(--display);font-style:italic;font-weight:700;font-size:14px;letter-spacing:.16em;color:var(--cyan);text-shadow:0 0 8px rgba(0,245,212,.6);text-transform:uppercase;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.lives{display:flex;gap:7px;min-height:14px;margin-top:6px}\n.lives i{display:block;width:30px;height:9px;border-radius:5px;background:var(--cyan);box-shadow:0 0 8px var(--cyan)}\n.meter{height:8px;margin-top:8px;border-radius:4px;background:rgba(255,255,255,.08);overflow:hidden}\n.meter b{display:block;height:100%;width:0;border-radius:4px;background:linear-gradient(90deg,var(--pink),var(--yellow));box-shadow:0 0 10px var(--pink);transition:width .2s ease}\n.legend{list-style:none;margin:6px 0 0;padding:0;display:grid;gap:8px}\n.legend li{display:grid;grid-template-columns:40px 1fr;align-items:center;gap:10px;font-size:13px;color:#e7d7ff;line-height:1.2}\n.legend li.on{color:#fff}\n.legend li.on .cap{animation:capPulse .5s ease-in-out infinite alternate}\n.cap{display:grid;place-items:center;height:18px;border-radius:9px;font-family:var(--display);font-style:italic;font-weight:900;font-size:13px;color:#12002b;background:var(--c);box-shadow:0 0 10px var(--c)}\n@keyframes capPulse{to{box-shadow:0 0 18px var(--c),0 0 4px #fff}}\n.legend .bar{display:block;height:3px;margin-top:4px;border-radius:2px;background:var(--c);transform-origin:0 50%;transform:scaleX(0);box-shadow:0 0 6px var(--c)}\n.keys{margin:6px 0 0;padding:0;list-style:none;display:grid;gap:6px;font-size:12.5px;color:#d9c6f7}\nkbd{display:inline-block;min-width:22px;padding:1px 6px;margin-right:6px;border-radius:5px;font-family:var(--display);font-style:italic;font-weight:800;font-size:12px;text-align:center;color:#fff;background:rgba(255,255,255,.08);box-shadow:inset 0 -2px 0 rgba(0,0,0,.4),0 0 0 1px rgba(0,245,212,.45)}\n\n/* ------------ controls ------------ */\n.dock{flex:0 0 auto;display:flex;align-items:center;justify-content:center;gap:12px;padding-top:10px}\n.ibtn{display:inline-flex;align-items:center;justify-content:center;gap:8px;height:40px;min-width:40px;padding:0 14px;border:0;border-radius:20px;cursor:pointer;\n  font-family:var(--display);font-style:italic;font-weight:800;font-size:14px;letter-spacing:.14em;text-transform:uppercase;\n  background:rgba(40,8,78,.85);box-shadow:inset 0 0 0 1.5px rgba(0,245,212,.7),0 0 12px rgba(0,245,212,.25);transition:transform .15s ease,box-shadow .2s ease}\n.ibtn:hover{transform:translateY(-1px);box-shadow:inset 0 0 0 1.5px var(--cyan),0 0 18px rgba(0,245,212,.55)}\n.ibtn:active{transform:scale(.96)}\n.ibtn svg{width:18px;height:18px}\n.ibtn[aria-pressed=\"true\"]{box-shadow:inset 0 0 0 1.5px var(--pink),0 0 14px rgba(255,46,151,.45)}\n.coin{font-family:var(--display);font-style:italic;font-weight:800;font-size:12px;letter-spacing:.3em;color:var(--orange);text-shadow:0 0 8px rgba(255,158,0,.7);text-transform:uppercase;animation:blink 1.1s steps(2,end) infinite}\n@keyframes blink{50%{opacity:.15}}\n:focus-visible{outline:2px solid var(--yellow);outline-offset:3px}\n\n/* ------------ overlays on the screen ------------ */\n.ov{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;padding:24px;text-align:center;\n  background:radial-gradient(90% 70% at 50% 45%,rgba(18,0,43,.35),rgba(18,0,43,.82));animation:ovIn .35s ease both}\n.ov[hidden]{display:none}\n@keyframes ovIn{from{opacity:0}to{opacity:1}}\n.ov h2{margin:0;font-family:var(--display);font-style:italic;font-weight:900;font-size:clamp(34px,8.5cqw,64px);line-height:.95;letter-spacing:.04em;color:#fff;text-transform:uppercase;\n  text-shadow:0 0 6px var(--pink),0 0 22px var(--pink),3px 3px 0 rgba(0,245,212,.8)}\n.ov .kick{margin:0;font-family:var(--display);font-style:italic;font-weight:800;font-size:13px;letter-spacing:.34em;color:var(--cyan);text-shadow:0 0 8px rgba(0,245,212,.7);text-transform:uppercase}\n.ov .score-line{margin:0;font-family:var(--display);font-style:italic;font-weight:900;font-size:28px;letter-spacing:.08em;color:var(--yellow);text-shadow:0 0 10px rgba(255,242,0,.65);font-variant-numeric:tabular-nums}\n.ov .note{margin:0;max-width:30ch;font-size:13px;line-height:1.5;color:#dccbf7}\n.ov .record{margin:0;font-family:var(--display);font-style:italic;font-weight:900;font-size:18px;letter-spacing:.2em;color:var(--pink);text-shadow:0 0 12px var(--pink);animation:blink .8s steps(2,end) infinite}\n.menu{display:grid;gap:10px;width:min(100%,290px);margin-top:6px}\n.mbtn{position:relative;display:flex;align-items:center;justify-content:space-between;gap:10px;padding:13px 18px;border:0;border-radius:10px;cursor:pointer;\n  font-family:var(--display);font-style:italic;font-weight:900;font-size:19px;letter-spacing:.12em;text-transform:uppercase;color:#fff;\n  background:linear-gradient(90deg,rgba(255,46,151,.28),rgba(155,93,229,.22));box-shadow:inset 0 0 0 2px var(--pink),0 0 16px rgba(255,46,151,.45);transform:skewX(-8deg);transition:transform .15s ease,background .2s ease}\n.mbtn span{transform:skewX(8deg)}\n.mbtn small{font-size:12px;letter-spacing:.16em;color:#ffd1ea;font-weight:700}\n.mbtn.alt{background:linear-gradient(90deg,rgba(0,245,212,.18),rgba(0,187,249,.16));box-shadow:inset 0 0 0 2px var(--cyan),0 0 16px rgba(0,245,212,.35)}\n.mbtn.alt small{color:#bff9ef}\n.mbtn:hover{transform:skewX(-8deg) translateX(4px)}\n.mbtn:active{transform:skewX(-8deg) scale(.97)}\n.title-ov{justify-content:flex-end;padding-bottom:12%;background:linear-gradient(180deg,rgba(18,0,43,0) 0%,rgba(18,0,43,.12) 45%,rgba(18,0,43,.72) 72%,rgba(18,0,43,.6) 100%)}\n.hi-line{margin:0;font-family:var(--display);font-style:italic;font-weight:800;font-size:15px;letter-spacing:.24em;color:#fff;text-shadow:0 0 8px var(--violet);font-variant-numeric:tabular-nums}\n.attract{position:absolute;left:14px;top:12px;font-family:var(--display);font-style:italic;font-weight:800;font-size:11px;letter-spacing:.3em;color:var(--yellow);text-shadow:0 0 8px rgba(255,242,0,.6);animation:blink 1.4s steps(2,end) infinite}\n\n.banner{position:absolute;left:0;right:0;top:44%;display:flex;flex-direction:column;align-items:center;gap:4px;pointer-events:none;opacity:0}\n.banner.show{animation:banner 2.1s cubic-bezier(.2,.9,.3,1) both}\n.banner b{font-family:var(--display);font-style:italic;font-weight:900;font-size:clamp(34px,9cqw,60px);letter-spacing:.06em;color:#fff;text-shadow:0 0 8px var(--cyan),0 0 26px var(--cyan),-3px 3px 0 rgba(255,46,151,.85);text-transform:uppercase;line-height:1}\n.banner span{font-family:var(--display);font-style:italic;font-weight:800;font-size:14px;letter-spacing:.4em;color:var(--yellow);text-shadow:0 0 10px rgba(255,242,0,.7);text-transform:uppercase}\n@keyframes banner{0%{opacity:0;transform:translateX(-30%) skewX(-18deg)}14%{opacity:1;transform:translateX(0) skewX(-8deg)}78%{opacity:1;transform:translateX(3%) skewX(-8deg)}100%{opacity:0;transform:translateX(40%) skewX(-18deg)}}\n.combo{position:absolute;right:14px;top:10px;pointer-events:none;text-align:right;opacity:0;transition:opacity .4s ease}\n.combo.on{opacity:1}\n.combo b{display:block;font-family:var(--display);font-style:italic;font-weight:900;font-size:clamp(26px,7cqw,40px);line-height:1;color:#fff;text-shadow:0 0 6px var(--orange),0 0 18px var(--pink);font-variant-numeric:tabular-nums}\n.combo span{font-family:var(--display);font-style:italic;font-weight:800;font-size:11px;letter-spacing:.3em;color:var(--orange)}\n.combo.pop b{animation:pop .32s cubic-bezier(.3,1.8,.5,1)}\n@keyframes pop{from{transform:scale(1.7) rotate(-6deg)}to{transform:none}}\n.screen{container-type:inline-size}\n.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);clip-path:inset(50%);white-space:nowrap}\n\n/* ------------ phones ------------ */\n@media (max-width:820px){\n  .cabinet{padding:8px 8px 6px}\n  .marquee{padding:4px 12px 6px;gap:10px;border-radius:10px}\n  .marquee::before,.marquee::after{width:28px}\n  .tagline{display:none}\n  .panel{display:none}\n  .deck{padding-top:8px}\n  .hud-top{display:flex;align-items:center;justify-content:space-between;gap:8px;height:36px;padding:0 6px 6px;font-family:var(--display);font-style:italic;font-weight:900}\n  .hud-top .h{display:flex;flex-direction:column;line-height:1}\n  .hud-top .h small{font-size:9px;letter-spacing:.24em;color:var(--dim);font-weight:800}\n  .hud-top .h strong{font-size:19px;letter-spacing:.05em;color:#fff;text-shadow:0 0 6px var(--pink),0 0 14px var(--pink);font-variant-numeric:tabular-nums}\n  .hud-top .h.c strong{text-shadow:0 0 6px var(--cyan),0 0 14px var(--cyan)}\n  .hud-top .lives i{width:18px;height:6px}\n  .bezel{border-radius:18px}\n  .bezel::before{inset:5px;border-radius:14px}\n  .screw{display:none}\n  .dock{padding-top:6px}\n  .ibtn{height:36px}\n}\n@media (prefers-reduced-motion:reduce){\n  .world .plane{animation:none}\n  .coin,.attract,.ov .record{animation:none}\n}\n</style>\n</head>\n<body>\n<div class=\"world\" aria-hidden=\"true\">\n  <div class=\"stars\"></div><div class=\"glow\"></div><div class=\"bigsun\"></div>\n  <div class=\"floor\"><div class=\"plane\"></div></div><div class=\"fade\"></div><div class=\"horizon\"></div>\n</div>\n\n<main class=\"cabinet\" id=\"cabinet\">\n  <header class=\"marquee\">\n    <h1 class=\"logo\" data-text=\"Hyperbrick\">Hyperbrick</h1>\n    <p class=\"tagline\">Neon breakout · cabinet no. 38</p>\n  </header>\n\n  <div class=\"deck\">\n    <aside class=\"panel\" aria-label=\"Score and stage\">\n      <section class=\"card\"><h2>Score</h2><p class=\"big\" data-hud=\"score\">000000</p></section>\n      <section class=\"card\"><h2>Hi-score</h2><p class=\"big vi\" data-hud=\"hi\">000000</p></section>\n      <section class=\"card\"><h2>Stage</h2><p class=\"big cy\" data-hud=\"stage\">01</p><p class=\"sub\" data-hud=\"stagename\">Attract mode</p></section>\n      <section class=\"card\"><h2>Lives</h2><div class=\"lives\" data-hud=\"lives\"></div></section>\n    </aside>\n\n    <div class=\"slot\" id=\"slot\">\n      <section class=\"bezel\" id=\"bezel\" aria-label=\"HYPERBRICK arcade screen\">\n        <span class=\"screw s1\"></span><span class=\"screw s2\"></span><span class=\"screw s3\"></span><span class=\"screw s4\"></span>\n        <div class=\"hud-top\" aria-hidden=\"true\">\n          <span class=\"h\"><small>SCORE</small><strong data-hud=\"score\">000000</strong></span>\n          <span class=\"h c\"><small>STAGE</small><strong data-hud=\"stage\">01</strong></span>\n          <span class=\"h\"><small>HI</small><strong data-hud=\"hi\">000000</strong></span>\n          <span class=\"h\"><small>LIVES</small><span class=\"lives\" data-hud=\"lives\"></span></span>\n        </div>\n        <div class=\"screen\" id=\"screen\">\n          <canvas id=\"game\" role=\"img\" aria-label=\"Playfield: neon bricks above a synthwave horizon, a glowing paddle and ball\"></canvas>\n          <div class=\"combo\" id=\"combo\" aria-hidden=\"true\"><b id=\"comboNum\">×2</b><span>COMBO</span></div>\n          <div class=\"banner\" id=\"banner\" aria-hidden=\"true\"><span id=\"bannerTop\">Stage 01</span><b id=\"bannerMain\">Love circuit</b></div>\n          <div class=\"glare\"></div>\n          <div class=\"scan\"></div>\n\n          <div class=\"ov title-ov\" id=\"ovTitle\">\n            <span class=\"attract\" aria-hidden=\"true\">ATTRACT MODE · DEMO</span>\n            <p class=\"kick\">Insert no coin · press start</p>\n            <div class=\"menu\">\n              <button type=\"button\" class=\"mbtn\" id=\"btnArcade\"><span>Arcade</span><small>5 stages</small></button>\n              <button type=\"button\" class=\"mbtn alt\" id=\"btnEndless\"><span>Endless</span><small>∞ waves</small></button>\n            </div>\n            <p class=\"hi-line\">HI-SCORE <span data-hud=\"hi\">000000</span></p>\n          </div>\n\n          <div class=\"ov\" id=\"ovPause\" hidden>\n            <p class=\"kick\">Game on hold</p>\n            <h2>Paused</h2>\n            <div class=\"menu\">\n              <button type=\"button\" class=\"mbtn alt\" id=\"btnResume\"><span>Resume</span><small>Space</small></button>\n              <button type=\"button\" class=\"mbtn\" id=\"btnQuit\"><span>Quit</span><small>to title</small></button>\n            </div>\n          </div>\n\n          <div class=\"ov\" id=\"ovOver\" hidden>\n            <p class=\"kick\" id=\"overKick\">Signal lost</p>\n            <h2 id=\"overTitle\">Game over</h2>\n            <p class=\"score-line\" id=\"overScore\">000000</p>\n            <p class=\"record\" id=\"overRecord\" hidden>New hi-score!</p>\n            <p class=\"note\" id=\"overNote\">Every brick you broke is still glowing somewhere.</p>\n            <div class=\"menu\">\n              <button type=\"button\" class=\"mbtn\" id=\"btnAgain\"><span>Play again</span><small>Space</small></button>\n              <button type=\"button\" class=\"mbtn alt\" id=\"btnOverAlt\"><span>Title</span><small>menu</small></button>\n            </div>\n          </div>\n        </div>\n      </section>\n    </div>\n\n    <aside class=\"panel\" aria-label=\"Combo and power-ups\">\n      <section class=\"card\"><h2>Combo</h2><p class=\"big yl\" data-hud=\"combo\">×0</p><div class=\"meter\" aria-hidden=\"true\"><b id=\"meter\"></b></div></section>\n      <section class=\"card\"><h2>Power-ups</h2>\n        <ul class=\"legend\">\n          <li id=\"lgM\"><span class=\"cap\" style=\"--c:#fff200\">M</span><span>Multi-ball<i class=\"bar\" style=\"--c:#fff200\"></i></span></li>\n          <li id=\"lgW\"><span class=\"cap\" style=\"--c:#00f5d4\">W</span><span>Wide paddle<i class=\"bar\" style=\"--c:#00f5d4\"></i></span></li>\n          <li id=\"lgL\"><span class=\"cap\" style=\"--c:#ff2e97\">L</span><span>Twin laser<i class=\"bar\" style=\"--c:#ff2e97\"></i></span></li>\n          <li id=\"lgS\"><span class=\"cap\" style=\"--c:#9b5de5\">S</span><span>Slow-mo<i class=\"bar\" style=\"--c:#9b5de5\"></i></span></li>\n        </ul>\n      </section>\n      <section class=\"card\"><h2>Controls</h2>\n        <ul class=\"keys\">\n          <li><kbd>←</kbd><kbd>→</kbd>or mouse / drag</li>\n          <li><kbd>Space</kbd>launch · pause</li>\n          <li><kbd>M</kbd>mute · <kbd>P</kbd>pause</li>\n        </ul>\n      </section>\n    </aside>\n  </div>\n\n  <nav class=\"dock\" aria-label=\"Cabinet controls\">\n    <button type=\"button\" class=\"ibtn\" id=\"btnMute\" aria-pressed=\"false\" aria-label=\"Mute sound\">\n      <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\" focusable=\"false\"><g fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 9h4l5-4v14l-5-4H4z\"/><path id=\"waveA\" d=\"M16.5 8.5a5 5 0 0 1 0 7\"/><path id=\"waveB\" d=\"M19.5 5.5a9 9 0 0 1 0 13\"/><path id=\"muteX\" d=\"M16 9l6 6M22 9l-6 6\" opacity=\"0\"/></g></svg>\n      <span id=\"muteLabel\">Sound</span>\n    </button>\n    <span class=\"coin\" aria-hidden=\"true\">Free play</span>\n    <button type=\"button\" class=\"ibtn\" id=\"btnPause\" aria-label=\"Pause game\">\n      <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\" focusable=\"false\"><g fill=\"currentColor\"><rect x=\"6\" y=\"5\" width=\"4\" height=\"14\" rx=\"1\"/><rect x=\"14\" y=\"5\" width=\"4\" height=\"14\" rx=\"1\"/></g></svg>\n      <span>Pause</span>\n    </button>\n  </nav>\n</main>\n<p class=\"sr-only\" id=\"live\" aria-live=\"polite\"></p>\n\n<script>\n(() => {\n'use strict';\nconst $ = id => document.getElementById(id);\nconst clamp = (v,a,b) => v<a?a:v>b?b:v;\nconst reduceMQ = matchMedia('(prefers-reduced-motion: reduce)');\nlet reduce = reduceMQ.matches;\nreduceMQ.addEventListener && reduceMQ.addEventListener('change', e => { reduce = e.matches; });\n\n/* ============ playfield constants (logical units) ============ */\nconst FW = 600;\nlet FH = 800;\nconst COLS = 13, GX = 12, GY = 92, CW = (FW - GX*2)/COLS, RH = 28, BH = 21;\nconst TOP = 26, BALL_R = 7, PADDLE_W = 98, PADDLE_WIDE = 158, PADDLE_H = 14;\nconst COLORS = {p:'#ff2e97', o:'#ff9e00', y:'#fff200', c:'#00f5d4', b:'#00bbf9', v:'#9b5de5'};\nconst KEYS = Object.keys(COLORS);\nconst POWERS = {\n  M:{name:'Multi-ball', color:'#fff200'},\n  W:{name:'Wide paddle', color:'#00f5d4'},\n  L:{name:'Twin laser', color:'#ff2e97'},\n  S:{name:'Slow-mo', color:'#9b5de5'}\n};\n\n/* ============ five hand-built stages (13 columns; capitals take two hits) ============ */\nconst LEVELS = [\n  {name:'Love circuit', rows:[\n    '..PPP...PPP..',\n    '.ppypp.ppppp.',\n    'ppypppppppppp',\n    'ppppppppppppp',\n    '.vvvvvvvvvvv.',\n    '..vvvvvvvvv..',\n    '...bbbbbbb...',\n    '....bbbbb....',\n    '.....ccc.....',\n    '......c......']},\n  {name:'Invader', rows:[\n    '...b.....b...',\n    '....b...b....',\n    '...CCCCCCC...',\n    '..cc.ccc.cc..',\n    '.ccccccccccc.',\n    '.c.ccccccc.c.',\n    '.v.v.....v.v.',\n    '....vv.vv....',\n    '.............',\n    'y.y.y.y.y.y.y']},\n  {name:'Spiral', rows:[\n    'ooooooooooooo',\n    '............o',\n    'pbbbbbbbbbb.o',\n    'p.........b.o',\n    'p.vvvvvvv.b.o',\n    'p.b.....v.b.o',\n    'p.b.Yyyyv.b.o',\n    'p.b.......b.o',\n    'p.bbbbbbbbb.o',\n    'p...........o',\n    'ppppppppppppp']},\n  {name:'Palm drive', rows:[\n    '...cc...cc...',\n    '.ccccc.ccccc.',\n    'cc..ccCcc..cc',\n    'c...c.O.c...c',\n    '....c.O.c....',\n    '......O......',\n    '.....O.......',\n    '.....O.......',\n    '....O........',\n    '....O........',\n    'yyyyyyyyyyyyy',\n    'ppppppppppppp']},\n  {name:'Hyper sun', rows:[\n    '.....yyy.....',\n    '...YYYYYYY...',\n    '..yyyyyyyyy..',\n    '.ooooooooooo.',\n    '.............',\n    'OOOOOOOOOOOOO',\n    '.............',\n    'ppppppppppppp',\n    '.............',\n    '.PPPPPPPPPPP.',\n    '.............',\n    '..vvvvvvvvv..']}\n];\nfunction endlessRows(wave){\n  const rows=[], n=Math.min(12,6+Math.floor(wave/2)), hard=Math.min(.55,.06+wave*.05);\n  const seed=wave*9301+49297;let s=seed;const rnd=()=>{s=(s*16807)%2147483647;return (s-1)/2147483646;};\n  const offs=Math.floor(rnd()*6);\n  for(let r=0;r<n;r++){\n    const half=[];for(let c=0;c<7;c++)half.push(rnd()<(.5+Math.min(.35,wave*.03))+(r%3===0?.2:0));\n    const key=KEYS[(r+offs)%6];let row='';\n    for(let c=0;c<COLS;c++){const on=half[c<7?c:12-c];row+=on?(rnd()<hard?key.toUpperCase():key):'.';}\n    rows.push(row);\n  }\n  if(!rows.some(r=>/[a-zA-Z]/.test(r)))rows[0]='ppppppppppppp';\n  return rows;\n}\n\n/* ============ canvas + layout ============ */\nconst cv=$('game'), ctx=cv.getContext('2d');\nconst slot=$('slot'), bezel=$('bezel'), screenEl=$('screen');\nlet scale=1, dpr=1, dispW=300, dispH=400;\nlet bgCanvas=document.createElement('canvas'), bgc=bgCanvas.getContext('2d');\nlet sprites={}, ballSprite=null;\n\nfunction layout(){\n  const mobile=innerWidth<=820;\n  const pad=mobile?8:20, hud=mobile?42:0;\n  bezel.style.setProperty('--pad',pad+'px');\n  const sw=slot.clientWidth, sh=slot.clientHeight;\n  const aw=Math.max(200,sw-pad*2), ah=Math.max(260,sh-pad*2-hud);\n  FH = mobile ? clamp(Math.round(FW*ah/aw/10)*10,780,1000) : 800;\n  dispW=aw; dispH=aw*FH/FW;\n  if(dispH>ah){dispH=ah;dispW=ah*FW/FH;}\n  dispW=Math.floor(dispW);dispH=Math.floor(dispH);\n  dpr=Math.min(2,window.devicePixelRatio||1);\n  scale=dispW/FW;\n  cv.style.width=dispW+'px';cv.style.height=dispH+'px';\n  cv.width=Math.round(dispW*dpr);cv.height=Math.round(dispH*dpr);\n  screenEl.style.width=dispW+'px';screenEl.style.height=dispH+'px';\n  bezel.style.width=(dispW+pad*2)+'px';\n  paddle.y=FH-72;\n  buildBackground();buildSprites();\n}\n\n/* ---- the synthwave sky, sun and mountains, painted once per resize ---- */\nfunction buildBackground(){\n  const s=scale*dpr;\n  bgCanvas.width=Math.round(FW*s);bgCanvas.height=Math.round(FH*s);\n  const g=bgc;g.setTransform(s,0,0,s,0,0);\n  const hz=FH*.6;\n  let gr=g.createLinearGradient(0,0,0,hz);\n  gr.addColorStop(0,'#0c001f');gr.addColorStop(.45,'#12002b');gr.addColorStop(.78,'#3a0a5e');gr.addColorStop(.95,'#8a1b72');gr.addColorStop(1,'#ff2e97');\n  g.fillStyle=gr;g.fillRect(0,0,FW,hz);\n  // stars\n  let sd=7;const rnd=()=>{sd=(sd*16807)%2147483647;return sd/2147483647;};\n  for(let i=0;i<110;i++){const x=rnd()*FW,y=rnd()*hz*.8,r=rnd()*1.2+.3;g.globalAlpha=.3+rnd()*.7;g.fillStyle=rnd()<.2?'#ffc6e6':'#ffffff';g.fillRect(x,y,r,r);}\n  g.globalAlpha=1;\n  // sun glow\n  const sx=FW/2,sy=hz-8,sr=Math.min(150,FW*.25);\n  gr=g.createRadialGradient(sx,sy,sr*.4,sx,sy,sr*2.3);gr.addColorStop(0,'rgba(255,90,160,.55)');gr.addColorStop(1,'rgba(255,46,151,0)');\n  g.fillStyle=gr;g.fillRect(0,0,FW,hz);\n  // striped sun on its own layer\n  const sc=document.createElement('canvas');sc.width=bgCanvas.width;sc.height=bgCanvas.height;const k=sc.getContext('2d');k.setTransform(s,0,0,s,0,0);\n  gr=k.createLinearGradient(0,sy-sr,0,sy+sr);gr.addColorStop(0,'#fff200');gr.addColorStop(.35,'#ffb800');gr.addColorStop(.62,'#ff5e7e');gr.addColorStop(1,'#ff2e97');\n  k.fillStyle=gr;k.beginPath();k.arc(sx,sy,sr,0,Math.PI*2);k.fill();\n  k.globalCompositeOperation='destination-out';\n  for(let i=0;i<7;i++){const y=sy-sr*.12+i*sr*.16,h=2+i*2.2;k.fillRect(sx-sr-2,y,sr*2+4,h);}\n  g.drawImage(sc,0,0,FW,FH);\n  // mountains with neon rims\n  const mount=(pts,fill,stroke)=>{g.beginPath();g.moveTo(0,hz);pts.forEach(([x,y])=>g.lineTo(x,y));g.lineTo(FW,hz);g.closePath();g.fillStyle=fill;g.fill();g.strokeStyle=stroke;g.lineWidth=1.5;g.shadowColor=stroke;g.shadowBlur=8;g.beginPath();g.moveTo(0,hz);pts.forEach(([x,y])=>g.lineTo(x,y));g.stroke();g.shadowBlur=0;};\n  mount([[0,hz-40],[40,hz-70],[78,hz-38],[118,hz-92],[160,hz-50],[196,hz-66],[236,hz-18],[270,hz-6],[330,hz-4],[372,hz-26],[410,hz-58],[446,hz-34],[482,hz-96],[528,hz-48],[566,hz-74],[600,hz-44]],'#1b0336','rgba(0,245,212,.8)');\n  mount([[0,hz-14],[60,hz-30],[112,hz-12],[170,hz-26],[228,hz-6],[372,hz-8],[430,hz-28],[492,hz-10],[548,hz-32],[600,hz-16]],'#120024','rgba(255,46,151,.7)');\n  // floor\n  gr=g.createLinearGradient(0,hz,0,FH);gr.addColorStop(0,'#2b0647');gr.addColorStop(.3,'#16012f');gr.addColorStop(1,'#0b0019');\n  g.fillStyle=gr;g.fillRect(0,hz,FW,FH-hz);\n  g.fillStyle='rgba(255,46,151,.9)';g.fillRect(0,hz-1,FW,2);\n}\n\n/* ---- neon brick sprites: glow baked in once ---- */\nfunction roundRect(g,x,y,w,h,r){g.beginPath();g.moveTo(x+r,y);g.arcTo(x+w,y,x+w,y+h,r);g.arcTo(x+w,y+h,x,y+h,r);g.arcTo(x,y+h,x,y,r);g.arcTo(x,y,x+w,y,r);g.closePath();}\nfunction buildSprites(){\n  const s=scale*dpr, pad=12, bw=CW-4, w=bw+pad*2, h=BH+pad*2;\n  sprites={};\n  for(const k of KEYS){\n    for(const armored of [false,true]){\n      const c=document.createElement('canvas');c.width=Math.ceil(w*s);c.height=Math.ceil(h*s);\n      const g=c.getContext('2d');g.setTransform(s,0,0,s,0,0);\n      const col=COLORS[k];\n      g.shadowColor=col;g.shadowBlur=12;\n      roundRect(g,pad,pad,bw,BH,5);\n      const gr=g.createLinearGradient(0,pad,0,pad+BH);\n      gr.addColorStop(0,hexA(col,armored?.85:.55));gr.addColorStop(1,hexA(col,armored?.45:.16));\n      g.fillStyle=gr;g.fill();\n      g.lineWidth=2;g.strokeStyle=col;g.stroke();\n      g.shadowBlur=0;\n      g.fillStyle='rgba(255,255,255,.55)';g.fillRect(pad+5,pad+3,bw-10,1.6);\n      if(armored){\n        g.strokeStyle='rgba(255,255,255,.85)';g.lineWidth=1.2;roundRect(g,pad+3.5,pad+3.5,bw-7,BH-7,3);g.stroke();\n        g.fillStyle='#fff';for(const [x,y] of [[pad+6,pad+BH/2],[pad+bw-6,pad+BH/2]]){g.beginPath();g.arc(x,y,1.6,0,6.3);g.fill();}\n      }\n      sprites[k+(armored?'2':'1')]=c;\n    }\n  }\n  // ball glow sprite\n  const b=document.createElement('canvas');const bs=64;b.width=b.height=bs;const bg=b.getContext('2d');\n  const gr=bg.createRadialGradient(bs/2,bs/2,0,bs/2,bs/2,bs/2);gr.addColorStop(0,'rgba(255,255,255,1)');gr.addColorStop(.18,'rgba(255,255,255,.95)');gr.addColorStop(.3,'rgba(120,250,235,.55)');gr.addColorStop(1,'rgba(0,245,212,0)');\n  bg.fillStyle=gr;bg.fillRect(0,0,bs,bs);ballSprite=b;\n}\nfunction hexA(hex,a){const n=parseInt(hex.slice(1),16);return `rgba(${n>>16&255},${n>>8&255},${n&255},${a})`;}\n\n/* ============ sound: tiny synth, created on first gesture ============ */\nconst Sound=(()=>{\n  let ac=null,master=null,noiseBuf=null,muted=false;\n  try{muted=localStorage.getItem('hyperbrick-muted')==='1';}catch(e){}\n  function init(){\n    if(ac){if(ac.state==='suspended')ac.resume();return;}\n    try{\n      ac=new (window.AudioContext||window.webkitAudioContext)();\n      const comp=ac.createDynamicsCompressor();comp.threshold.value=-14;comp.ratio.value=6;\n      master=ac.createGain();master.gain.value=muted?0:.55;master.connect(comp);comp.connect(ac.destination);\n      noiseBuf=ac.createBuffer(1,ac.sampleRate*.25,ac.sampleRate);const d=noiseBuf.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;\n    }catch(e){ac=null;}\n  }\n  function tone(f,dur,type,vol,f2,delay){\n    if(!ac||muted)return;\n    const t=ac.currentTime+(delay||0),o=ac.createOscillator(),g=ac.createGain();\n    o.type=type||'square';o.frequency.setValueAtTime(f,t);if(f2)o.frequency.exponentialRampToValueAtTime(f2,t+dur);\n    g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(vol||.1,t+.006);g.gain.exponentialRampToValueAtTime(.0001,t+dur);\n    o.connect(g);g.connect(master);o.start(t);o.stop(t+dur+.03);\n  }\n  function noise(dur,freq,vol){\n    if(!ac||muted||!noiseBuf)return;\n    const t=ac.currentTime,src=ac.createBufferSource(),f=ac.createBiquadFilter(),g=ac.createGain();\n    src.buffer=noiseBuf;f.type='bandpass';f.frequency.value=freq;f.Q.value=1.4;\n    g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(.0001,t+dur);\n    src.connect(f);f.connect(g);g.connect(master);src.start(t);src.stop(t+dur+.02);\n  }\n  const PENTA=[0,3,5,7,10];\n  return{\n    init,\n    get muted(){return muted;},\n    setMuted(m){muted=m;if(master)master.gain.setTargetAtTime(m?0:.55,ac.currentTime,.02);try{localStorage.setItem('hyperbrick-muted',m?'1':'0');}catch(e){}},\n    brick(combo){const i=Math.min(combo,19),f=261.63*Math.pow(2,(PENTA[i%5]+12*Math.floor(i/5))/12);tone(f,.13,'square',.07);tone(f*2,.09,'triangle',.05);noise(.08,2400+i*120,.12);},\n    armor(){tone(1180,.05,'square',.05,760);noise(.05,5200,.08);},\n    paddle(){tone(174,.09,'square',.09,262);},\n    wall(){tone(620,.035,'triangle',.05);},\n    launch(){tone(260,.14,'square',.07,720);},\n    power(){[523.25,659.25,783.99,1046.5].forEach((f,i)=>tone(f,.1,'triangle',.09,null,i*.055));},\n    laser(){tone(1500,.07,'sawtooth',.025,380);},\n    lose(){tone(440,.7,'sawtooth',.09,52);noise(.4,500,.12);},\n    clear(){[392,493.88,587.33,739.99,783.99,987.77,1174.66,1567.98].forEach((f,i)=>tone(f,.14,'square',.06,null,i*.06));},\n    over(){[392,329.63,261.63,196].forEach((f,i)=>tone(f,.28,'triangle',.1,f*.97,i*.2));}\n  };\n})();\n\n/* ============ game state ============ */\nlet ui='title';            // title | game | paused | over | victory\nlet phase='serve';         // serve | play | clear\nlet endless=false, stageIdx=0, wave=1;\nlet score=0, hi=0, lives=3, combo=0, bestCombo=0;\nlet bricks=[], grid=[], breakable=0;\nlet balls=[], caps=[], beams=[];\nlet wideT=0, laserT=0, slowT=0, laserCd=0;\nlet shake=0, flash=0, flashCol='255,255,255', hitStop=0, clearT=0, serveT=0, gridPhase=0, time=0;\nconst paddle={x:FW/2,y:FH-72,w:PADDLE_W,tw:PADDLE_W,sq:0,tx:FW/2,vx:0};\ntry{hi=parseInt(localStorage.getItem('hyperbrick-hi')||'0',10)||0;}catch(e){}\n\nconst MAXP=520, parts=[];\nfor(let i=0;i<MAXP;i++)parts.push({on:false,x:0,y:0,vx:0,vy:0,r:0,vr:0,life:0,max:1,w:3,h:3,col:'#fff',kind:0});\nconst pops=[];\n\nfunction loadStage(){\n  const rows = endless ? endlessRows(wave) : LEVELS[stageIdx].rows;\n  bricks=[];grid=[];breakable=0;\n  rows.forEach((row,r)=>{\n    grid[r]=[];\n    for(let c=0;c<COLS;c++){\n      const ch=row[c]||'.';\n      if(ch==='.'){grid[r][c]=null;continue;}\n      const k=ch.toLowerCase(),hp=ch===k?1:2;\n      const b={x:GX+c*CW+2,y:GY+r*RH,w:CW-4,h:BH,k,hp,max:hp,alive:true,flash:0,r,c,appear:(r*COLS+c)*.012};\n      grid[r][c]=b;bricks.push(b);breakable++;\n    }\n  });\n  caps=[];beams=[];\n}\nfunction resetPaddle(){paddle.tw=PADDLE_W;wideT=0;laserT=0;slowT=0;}\nfunction serve(){\n  balls=[{x:paddle.x,y:paddle.y-PADDLE_H/2-BALL_R-1,vx:0,vy:0,trail:[],stuck:true,off:0}];\n  phase='serve';serveT=0;combo=0;updateCombo();\n}\nfunction baseSpeed(){return (endless?440+Math.min(160,wave*14):420+stageIdx*18);}\nfunction launch(){\n  if(phase!=='serve')return;\n  const sp=baseSpeed(),a=(Math.random()*.5-.25);\n  for(const b of balls){if(b.stuck){b.stuck=false;b.vx=Math.sin(a)*sp;b.vy=-Math.cos(a)*sp;}}\n  phase='play';if(ui==='game')Sound.launch();\n}\nfunction stageName(){return endless?'Wave '+wave:LEVELS[stageIdx].name;}\nfunction stageNum(){return endless?wave:stageIdx+1;}\n\nfunction startGame(isEndless,keepScore){\n  Sound.init();\n  endless=isEndless;stageIdx=0;wave=1;\n  if(!keepScore){score=0;lives=3;}\n  bestCombo=0;ui='game';\n  hideAll();loadStage();resetPaddle();serve();showBanner();hud(true);\n  say((endless?'Endless mode. ':'Arcade mode. ')+'Stage '+stageNum()+': '+stageName()+'. Press space or tap to launch.');\n  cv.focus({preventScroll:true});\n}\nfunction toTitle(){\n  ui='title';hideAll();$('ovTitle').hidden=false;\n  endless=false;stageIdx=Math.floor(Math.random()*LEVELS.length);loadStage();resetPaddle();serve();hud(true);\n  setTimeout(()=>{$('btnArcade').focus({preventScroll:true});},50);\n}\nfunction hideAll(){['ovTitle','ovPause','ovOver'].forEach(id=>$(id).hidden=true);}\nfunction pause(){if(ui!=='game')return;ui='paused';$('ovPause').hidden=false;$('btnResume').focus({preventScroll:true});say('Paused.');}\nfunction resume(){if(ui!=='paused')return;ui='game';$('ovPause').hidden=true;last=performance.now();cv.focus({preventScroll:true});}\nfunction gameOver(){\n  ui='over';Sound.over();\n  const rec=score>hi;if(rec){hi=score;try{localStorage.setItem('hyperbrick-hi',String(hi));}catch(e){}}\n  $('overKick').textContent='Signal lost · '+stageName();\n  $('overTitle').textContent='Game over';\n  $('overScore').textContent=pad6(score);\n  $('overRecord').hidden=!rec;\n  $('overNote').textContent='Best combo ×'+bestCombo+'. Every brick you broke is still glowing somewhere.';\n  $('btnAgain').querySelector('span').textContent='Play again';\n  $('btnOverAlt').querySelector('span').textContent='Title';\n  $('btnOverAlt').dataset.act='title';\n  $('ovOver').hidden=false;$('btnAgain').focus({preventScroll:true});hud(true);\n  say('Game over. Score '+score+(rec?'. New high score!':'.'));\n}\nfunction victory(){\n  ui='victory';Sound.clear();\n  const rec=score>hi;if(rec){hi=score;try{localStorage.setItem('hyperbrick-hi',String(hi));}catch(e){}}\n  $('overKick').textContent='All five stages cleared';\n  $('overTitle').textContent='Circuit complete';\n  $('overScore').textContent=pad6(score);\n  $('overRecord').hidden=!rec;\n  $('overNote').textContent='The grid keeps going. Carry your score and lives into endless mode?';\n  $('btnAgain').querySelector('span').textContent='Go endless';\n  $('btnOverAlt').querySelector('span').textContent='Title';\n  $('btnOverAlt').dataset.act='title';\n  $('ovOver').hidden=false;$('btnAgain').focus({preventScroll:true});hud(true);\n  say('Circuit complete! Score '+score+'.');\n}\nfunction nextStage(){\n  if(ui==='title'){stageIdx=(stageIdx+1+Math.floor(Math.random()*(LEVELS.length-1)))%LEVELS.length;loadStage();resetPaddle();serve();return;}\n  if(endless)wave++;\n  else if(stageIdx>=LEVELS.length-1){victory();return;}\n  else stageIdx++;\n  loadStage();resetPaddle();serve();showBanner();hud(true);\n  say('Stage '+stageNum()+': '+stageName()+'.');\n}\n\n/* ============ fx ============ */\nfunction spawn(x,y,vx,vy,life,col,w,h,kind){\n  for(const p of parts){if(!p.on){p.on=true;p.x=x;p.y=y;p.vx=vx;p.vy=vy;p.life=p.max=life;p.col=col;p.w=w;p.h=h;p.r=Math.random()*6.28;p.vr=(Math.random()-.5)*18;p.kind=kind||0;return p;}}\n  return null;\n}\nfunction shatter(b,ball){\n  const col=COLORS[b.k],n=reduce?8:20,cx=b.x+b.w/2,cy=b.y+b.h/2;\n  const dx=ball?ball.vx*.25:0,dy=ball?ball.vy*.25:0;\n  for(let i=0;i<n;i++){\n    const a=Math.random()*Math.PI*2,sp=60+Math.random()*260;\n    spawn(cx+(Math.random()-.5)*b.w,cy+(Math.random()-.5)*b.h,Math.cos(a)*sp+dx,Math.sin(a)*sp+dy-60,.5+Math.random()*.6,col,2+Math.random()*6,2+Math.random()*3,0);\n  }\n  spawn(cx,cy,0,0,.35,col,b.w*.7,0,1); // shock ring\n  for(let i=0;i<5;i++)spawn(cx,cy,(Math.random()-.5)*80,(Math.random()-.5)*80,.25,'#ffffff',1.5,1.5,0);\n}\nfunction pop(x,y,text,col,size){pops.push({x,y,text,col,size:size||16,t:0});if(pops.length>18)pops.shift();}\nfunction addShake(v){if(!reduce)shake=Math.min(16,shake+v);}\n\n/* ============ collisions ============ */\nfunction hitBrick(b,ball){\n  b.hp--;b.flash=1;\n  if(b.hp>0){if(ui==='game')Sound.armor();addShake(1.5);spawn(b.x+b.w/2,b.y+b.h/2,0,0,.25,'#ffffff',b.w*.5,0,1);return;}\n  b.alive=false;grid[b.r][b.c]=null;breakable--;\n  combo++;bestCombo=Math.max(bestCombo,combo);\n  const pts=(b.max===2?160:100)*Math.min(combo,12);\n  if(ui==='game'){score+=pts;Sound.brick(combo);}\n  pop(b.x+b.w/2,b.y+b.h/2,'+'+pts,COLORS[b.k],combo>=5?20:15);\n  shatter(b,ball);addShake(2.4+Math.min(4,combo*.35));\n  if(combo>=6&&!reduce)hitStop=.035;\n  updateCombo(true);\n  if(Math.random()<(ui==='title'?.12:.15)&&caps.length<3){\n    const types='MWLS';caps.push({x:b.x+b.w/2,y:b.y+b.h/2,t:types[Math.floor(Math.random()*4)],ph:Math.random()*6});\n  }\n  if(breakable<=0)stageClear();\n}\nfunction stageClear(){\n  phase='clear';clearT=ui==='title'?1.2:2.3;flash=reduce?.2:.7;flashCol='255,255,255';\n  for(const b of balls){b.vx=0;b.vy=0;}\n  if(ui==='game'){Sound.clear();const bonus=lives*500;score+=bonus;pop(FW/2,FH*.5,'STAGE CLEAR +'+bonus,'#fff200',28);hud(true);say('Stage clear! Bonus '+bonus+'.');}\n  for(let i=0;i<(reduce?20:80);i++){const a=Math.random()*6.28,sp=100+Math.random()*420;spawn(FW/2,FH*.42,Math.cos(a)*sp,Math.sin(a)*sp,.8+Math.random()*.8,COLORS[KEYS[i%6]],3+Math.random()*5,2+Math.random()*3,0);}\n}\nfunction collideBricks(ball){\n  const r=BALL_R;\n  const c0=Math.floor((ball.x-r-GX)/CW),c1=Math.floor((ball.x+r-GX)/CW);\n  const r0=Math.floor((ball.y-r-GY)/RH),r1=Math.floor((ball.y+r-GY)/RH);\n  let best=null,bestD=Infinity;\n  for(let rr=r0;rr<=r1;rr++){\n    const row=grid[rr];if(!row)continue;\n    for(let cc=c0;cc<=c1;cc++){\n      const b=row[cc];if(!b||!b.alive)continue;\n      const nx=clamp(ball.x,b.x,b.x+b.w),ny=clamp(ball.y,b.y,b.y+b.h),dx=ball.x-nx,dy=ball.y-ny,d=dx*dx+dy*dy;\n      if(d<r*r&&d<bestD){bestD=d;best=b;}\n    }\n  }\n  if(!best)return false;\n  const cx=best.x+best.w/2,cy=best.y+best.h/2;\n  const ox=best.w/2+r-Math.abs(ball.x-cx),oy=best.h/2+r-Math.abs(ball.y-cy);\n  if(ox<oy){const s=Math.sign(ball.x-cx)||1;ball.vx=s*Math.abs(ball.vx);ball.x+=s*ox;}\n  else{const s=Math.sign(ball.y-cy)||1;ball.vy=s*Math.abs(ball.vy);ball.y+=s*oy;}\n  hitBrick(best,ball);\n  return true;\n}\nfunction paddleHit(ball){\n  const off=clamp((ball.x-paddle.x)/(paddle.w/2),-1,1);\n  const sp=Math.min(760,Math.hypot(ball.vx,ball.vy)+5);\n  const a=off*1.08;\n  ball.vx=Math.sin(a)*sp;ball.vy=-Math.cos(a)*sp;\n  ball.y=paddle.y-PADDLE_H/2-BALL_R;\n  paddle.sq=1;combo=0;updateCombo();\n  if(ui==='game')Sound.paddle();\n  for(let i=0;i<(reduce?3:9);i++)spawn(ball.x,paddle.y-PADDLE_H/2,(Math.random()-.5)*220,-Math.random()*200,.35,'#00f5d4',2,2,0);\n}\nfunction stepBall(ball,dt){\n  const sp=Math.hypot(ball.vx,ball.vy);\n  const n=Math.max(1,Math.ceil(sp*dt/(BALL_R*.6)));\n  const sdt=dt/n;\n  for(let i=0;i<n;i++){\n    ball.x+=ball.vx*sdt;ball.y+=ball.vy*sdt;\n    if(ball.x<BALL_R){ball.x=BALL_R;ball.vx=Math.abs(ball.vx);if(ui==='game')Sound.wall();}\n    else if(ball.x>FW-BALL_R){ball.x=FW-BALL_R;ball.vx=-Math.abs(ball.vx);if(ui==='game')Sound.wall();}\n    if(ball.y<TOP+BALL_R){ball.y=TOP+BALL_R;ball.vy=Math.abs(ball.vy);if(ui==='game')Sound.wall();}\n    if(ball.vy>0&&ball.y+BALL_R>=paddle.y-PADDLE_H/2&&ball.y-BALL_R<=paddle.y+PADDLE_H/2&&Math.abs(ball.x-paddle.x)<=paddle.w/2+BALL_R*.8){paddleHit(ball);}\n    if(ball.y-BALL_R<GY+RH*grid.length+4)collideBricks(ball);\n    if(phase!=='play')return;\n  }\n  // keep angles lively: never let a ball crawl horizontally\n  const s2=Math.hypot(ball.vx,ball.vy);\n  if(s2>0&&Math.abs(ball.vy)<s2*.28){ball.vy=Math.sign(ball.vy||-1)*s2*.28;ball.vx=Math.sign(ball.vx)*Math.sqrt(s2*s2-ball.vy*ball.vy);}\n}\nfunction applyPower(t){\n  if(ui==='game'){Sound.power();say(POWERS[t].name+'!');}\n  pop(paddle.x,paddle.y-34,POWERS[t].name.toUpperCase(),POWERS[t].color,17);\n  if(t==='M'){\n    const src=balls.filter(b=>!b.stuck).slice(0,3);\n    if(!src.length&&balls[0])src.push(balls[0]);\n    for(const b of src){for(const da of [-.35,.35]){if(balls.length>=9)break;const sp=Math.max(380,Math.hypot(b.vx,b.vy)),a=Math.atan2(b.vx,-b.vy)+da;balls.push({x:b.x,y:b.y,vx:Math.sin(a)*sp,vy:-Math.abs(Math.cos(a)*sp),trail:[],stuck:false});}}\n    if(phase==='serve')launch();\n  }\n  else if(t==='W'){paddle.tw=PADDLE_WIDE;wideT=14;}\n  else if(t==='L'){laserT=10;laserCd=0;}\n  else if(t==='S'){slowT=8;}\n  flash=Math.max(flash,.25);flashCol='255,255,255';\n}\n\n/* ============ input ============ */\nconst keys={left:false,right:false};\nlet pointer={active:false,type:'mouse',sx:0,spx:0,moved:0,t:0,id:null};\nfunction screenX(clientX){const r=cv.getBoundingClientRect();return (clientX-r.left)/r.width*FW;}\nwindow.addEventListener('pointermove',e=>{\n  if(ui!=='game')return;\n  if(e.pointerType==='mouse'){paddle.tx=screenX(e.clientX);}\n  else if(pointer.active&&e.pointerId===pointer.id){\n    const dx=e.clientX-pointer.sx;pointer.moved=Math.max(pointer.moved,Math.abs(dx));\n    paddle.tx=clamp(pointer.spx+dx/scale*1.25,0,FW);\n  }\n});\nwindow.addEventListener('pointerdown',e=>{\n  Sound.init();\n  if(e.target.closest('button'))return;\n  if(ui!=='game')return;\n  if(e.pointerType==='mouse'){paddle.tx=screenX(e.clientX);if(e.target===cv||screenEl.contains(e.target)){if(phase==='serve')launch();}}\n  else{pointer={active:true,type:e.pointerType,sx:e.clientX,spx:paddle.tx,moved:0,t:performance.now(),id:e.pointerId};}\n});\nwindow.addEventListener('pointerup',e=>{\n  if(pointer.active&&e.pointerId===pointer.id){\n    if(pointer.moved<12&&performance.now()-pointer.t<320&&ui==='game'&&phase==='serve')launch();\n    pointer.active=false;\n  }\n});\nwindow.addEventListener('pointercancel',()=>{pointer.active=false;});\nwindow.addEventListener('keydown',e=>{\n  Sound.init();\n  const k=e.key;\n  if(k==='ArrowLeft'||k==='a'||k==='A'){keys.left=true;if(ui==='game')e.preventDefault();}\n  else if(k==='ArrowRight'||k==='d'||k==='D'){keys.right=true;if(ui==='game')e.preventDefault();}\n  else if(k===' '||k==='Spacebar'){\n    if(e.target.closest&&e.target.closest('button')&&ui!=='game')return;\n    e.preventDefault();\n    if(ui==='game'){if(phase==='serve')launch();else pause();}\n    else if(ui==='paused')resume();\n    else if(ui==='title')startGame(false);\n    else if(ui==='over'||ui==='victory')$('btnAgain').click();\n  }\n  else if(k==='p'||k==='P'||k==='Escape'){if(ui==='game')pause();else if(ui==='paused')resume();}\n  else if(k==='m'||k==='M'){toggleMute();}\n});\nwindow.addEventListener('keyup',e=>{\n  const k=e.key;\n  if(k==='ArrowLeft'||k==='a'||k==='A')keys.left=false;\n  if(k==='ArrowRight'||k==='d'||k==='D')keys.right=false;\n});\ncv.tabIndex=0;\n\n$('btnArcade').addEventListener('click',()=>startGame(false));\n$('btnEndless').addEventListener('click',()=>startGame(true));\n$('btnResume').addEventListener('click',resume);\n$('btnQuit').addEventListener('click',()=>{toTitle();});\n$('btnAgain').addEventListener('click',()=>{\n  if(ui==='victory'){const sc=score,lv=lives;startGame(true,true);score=sc;lives=lv;hud(true);}\n  else startGame(endless);\n});\n$('btnOverAlt').addEventListener('click',()=>toTitle());\n$('btnPause').addEventListener('click',()=>{if(ui==='game')pause();else if(ui==='paused')resume();});\n$('btnMute').addEventListener('click',toggleMute);\nfunction toggleMute(){Sound.init();Sound.setMuted(!Sound.muted);syncMute();}\nfunction syncMute(){\n  const m=Sound.muted;$('btnMute').setAttribute('aria-pressed',String(m));$('btnMute').setAttribute('aria-label',m?'Unmute sound':'Mute sound');\n  $('muteLabel').textContent=m?'Muted':'Sound';$('muteX').setAttribute('opacity',m?'1':'0');$('waveA').setAttribute('opacity',m?'0':'1');$('waveB').setAttribute('opacity',m?'0':'1');\n}\nsyncMute();\n\n/* ============ HUD ============ */\nconst hudEls={};['score','hi','stage','stagename','lives','combo'].forEach(k=>hudEls[k]=Array.from(document.querySelectorAll(`[data-hud=\"${k}\"]`)));\nconst pad6=n=>String(Math.max(0,Math.floor(n))).padStart(6,'0');\nlet hudCache={};\nfunction setHud(k,v,html){if(hudCache[k]===v)return;hudCache[k]=v;hudEls[k].forEach(el=>{if(html)el.innerHTML=v;else el.textContent=v;});}\nfunction hud(force){\n  if(force)hudCache={};\n  setHud('score',pad6(ui==='title'?0:score));\n  setHud('hi',pad6(Math.max(hi,ui==='title'?0:score)));\n  setHud('stage',String(stageNum()).padStart(2,'0'));\n  setHud('stagename',ui==='title'?'Attract mode':stageName());\n  setHud('lives','<i></i>'.repeat(ui==='title'?3:Math.max(0,lives)),true);\n}\nconst comboEl=$('combo'),comboNum=$('comboNum'),meter=$('meter');let comboT=0;\nfunction updateCombo(bump){\n  setHud('combo','×'+combo);\n  meter.style.width=Math.min(100,combo/12*100)+'%';\n  if(combo>=2){comboNum.textContent='×'+combo;comboEl.classList.add('on');if(bump){comboEl.classList.remove('pop');void comboEl.offsetWidth;comboEl.classList.add('pop');}comboT=1.4;}\n}\nconst legend={M:$('lgM'),W:$('lgW'),L:$('lgL'),S:$('lgS')};\nfunction syncLegend(){\n  const st={M:balls.length>1?1:0,W:wideT/14,L:laserT/10,S:slowT/8};\n  for(const k in st){const v=clamp(st[k],0,1);legend[k].classList.toggle('on',v>0);legend[k].querySelector('.bar').style.transform=`scaleX(${v.toFixed(3)})`;}\n}\nconst bannerEl=$('banner');\nfunction showBanner(){\n  $('bannerTop').textContent=(endless?'Endless · wave ':'Stage ')+String(stageNum()).padStart(2,'0');\n  $('bannerMain').textContent=stageName();\n  bannerEl.classList.remove('show');void bannerEl.offsetWidth;bannerEl.classList.add('show');\n}\nconst live=$('live');function say(s){live.textContent=s;}\n\n/* ============ update ============ */\nfunction aiPaddle(dt){\n  let target=FW/2,best=null;\n  for(const b of balls){if(b.stuck)continue;if(b.vy>0&&(!best||b.y>best.y))best=b;}\n  if(!best)best=balls[0];\n  if(best){\n    let x=best.x;\n    if(best.vy>0){const t=(paddle.y-best.y)/best.vy;x=best.x+best.vx*t;for(let i=0;i<4;i++){if(x<0)x=-x;if(x>FW)x=2*FW-x;}}\n    target=x+Math.sin(time*.9)*paddle.w*.32;\n  }\n  const d=target-paddle.x;paddle.x+=clamp(d,-820*dt,820*dt);paddle.tx=paddle.x;\n}\nfunction update(dt){\n  time+=dt;\n  gridPhase=(gridPhase+dt*(reduce?.15:.55+Math.min(combo,14)*.08))%1;\n  if(comboT>0){comboT-=dt;if(comboT<=0)comboEl.classList.remove('on');}\n  updateFx(dt);\n  if(ui!=='game'&&ui!=='title')return;\n  if(hitStop>0){hitStop-=dt;return;}\n  const slow=slowT>0?.55:1;\n\n  // paddle\n  if(ui==='title')aiPaddle(dt);\n  else{\n    if(keys.left||keys.right){paddle.vx=clamp(paddle.vx+(keys.right-keys.left)*5200*dt,-900,900);paddle.tx=paddle.x+paddle.vx*dt;}\n    else paddle.vx*=Math.exp(-dt*18);\n    paddle.x+=(paddle.tx-paddle.x)*Math.min(1,dt*26);\n  }\n  paddle.w+=(paddle.tw-paddle.w)*Math.min(1,dt*9);\n  paddle.x=clamp(paddle.x,paddle.w/2,FW-paddle.w/2);paddle.tx=clamp(paddle.tx,paddle.w/2,FW-paddle.w/2);\n  paddle.sq*=Math.exp(-dt*9);\n\n  // timers\n  if(wideT>0){wideT-=dt;if(wideT<=0)paddle.tw=PADDLE_W;}\n  if(slowT>0)slowT-=dt;\n  if(laserT>0){laserT-=dt;laserCd-=dt;if(laserCd<=0&&phase==='play'){laserCd=.24;for(const s of [-1,1])beams.push({x:paddle.x+s*(paddle.w/2-8),y:paddle.y-PADDLE_H});if(ui==='game')Sound.laser();}}\n\n  if(phase==='clear'){clearT-=dt;if(clearT<=0)nextStage();return;}\n  if(phase==='serve'){\n    serveT+=dt;\n    const b=balls[0];if(b){b.x=paddle.x+Math.sin(time*3)*paddle.w*.18;b.y=paddle.y-PADDLE_H/2-BALL_R-1;trailPush(b);}\n    if(ui==='title'&&serveT>.7)launch();\n  }\n  else if(phase==='play'){\n    for(const b of balls){stepBall(b,dt*slow);trailPush(b);}\n    if(phase!=='play')return;\n    balls=balls.filter(b=>b.y-BALL_R<FH+8);\n    if(!balls.length){ballLost();return;}\n  }\n\n  // capsules\n  for(let i=caps.length-1;i>=0;i--){\n    const c=caps[i];c.y+=150*dt*slow;c.ph+=dt*4;\n    if(c.y>paddle.y-PADDLE_H/2-9&&c.y<paddle.y+PADDLE_H/2+9&&Math.abs(c.x-paddle.x)<paddle.w/2+18){caps.splice(i,1);applyPower(c.t);continue;}\n    if(c.y>FH+20)caps.splice(i,1);\n  }\n  // laser beams\n  for(let i=beams.length-1;i>=0;i--){\n    const bm=beams[i];bm.y-=900*dt;\n    if(bm.y<TOP){beams.splice(i,1);continue;}\n    const c=Math.floor((bm.x-GX)/CW),r=Math.floor((bm.y-GY)/RH),row=grid[r],b=row&&row[c];\n    if(b&&b.alive&&bm.y<b.y+b.h&&bm.y>b.y){beams.splice(i,1);hitBrick(b,null);if(phase!=='play')return;}\n  }\n}\nfunction ballLost(){\n  if(ui==='title'){serve();return;}\n  lives--;Sound.lose();addShake(14);flash=reduce?.2:.55;flashCol='255,46,151';\n  combo=0;updateCombo();caps=[];beams=[];resetPaddle();hud(true);\n  if(lives<=0){gameOver();return;}\n  say('Ball lost. '+lives+(lives===1?' life':' lives')+' left.');\n  serve();\n}\nfunction trailPush(b){b.trail.push(b.x,b.y);if(b.trail.length>28)b.trail.splice(0,2);}\nfunction updateFx(dt){\n  for(const p of parts){\n    if(!p.on)continue;\n    p.life-=dt;if(p.life<=0){p.on=false;continue;}\n    if(p.kind===0){p.vy+=520*dt;p.vx*=Math.exp(-dt*1.2);p.x+=p.vx*dt;p.y+=p.vy*dt;p.r+=p.vr*dt;}\n  }\n  for(let i=pops.length-1;i>=0;i--){pops[i].t+=dt;if(pops[i].t>1)pops.splice(i,1);}\n  for(const b of bricks)if(b.flash>0)b.flash=Math.max(0,b.flash-dt*6);\n  shake*=Math.exp(-dt*11);if(shake<.05)shake=0;\n  flash=Math.max(0,flash-dt*2.2);\n}\n\n/* ============ render ============ */\nfunction render(){\n  const s=scale*dpr;\n  const sx=shake?(Math.random()-.5)*shake*2:0,sy=shake?(Math.random()-.5)*shake*2:0;\n  ctx.setTransform(1,0,0,1,0,0);\n  ctx.globalCompositeOperation='source-over';ctx.globalAlpha=1;\n  ctx.drawImage(bgCanvas,0,0);\n  ctx.setTransform(s,0,0,s,sx*s,sy*s);\n  drawGrid();\n  // ceiling rail\n  ctx.fillStyle='rgba(0,245,212,.85)';ctx.fillRect(0,TOP-3,FW,2);\n  ctx.fillStyle='rgba(0,245,212,.18)';ctx.fillRect(0,TOP-8,FW,8);\n\n  // bricks\n  const pad=12;\n  for(const b of bricks){\n    if(!b.alive)continue;\n    const spr=sprites[b.k+(b.hp>1?'2':'1')];\n    ctx.drawImage(spr,b.x-pad,b.y-pad,b.w+pad*2,b.h+pad*2);\n    if(b.max===2&&b.hp===1){ctx.strokeStyle='rgba(255,255,255,.7)';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(b.x+b.w*.3,b.y+2);ctx.lineTo(b.x+b.w*.42,b.y+b.h*.55);ctx.lineTo(b.x+b.w*.36,b.y+b.h-2);ctx.moveTo(b.x+b.w*.42,b.y+b.h*.55);ctx.lineTo(b.x+b.w*.6,b.y+b.h*.45);ctx.stroke();}\n    if(b.flash>0){ctx.globalAlpha=b.flash;ctx.fillStyle='#fff';roundRect(ctx,b.x-1,b.y-1,b.w+2,b.h+2,5);ctx.fill();ctx.globalAlpha=1;}\n  }\n\n  ctx.globalCompositeOperation='lighter';\n  // laser beams\n  for(const bm of beams){ctx.fillStyle='rgba(255,46,151,.35)';ctx.fillRect(bm.x-3,bm.y,6,22);ctx.fillStyle='#ffd1ea';ctx.fillRect(bm.x-1,bm.y,2,22);}\n  // capsules\n  ctx.globalCompositeOperation='source-over';\n  for(const c of caps){\n    const col=POWERS[c.t].color,w=36,h=16;\n    ctx.save();ctx.translate(c.x,c.y);ctx.rotate(Math.sin(c.ph)*.12);\n    ctx.shadowColor=col;ctx.shadowBlur=14;ctx.fillStyle=col;roundRect(ctx,-w/2,-h/2,w,h,8);ctx.fill();\n    ctx.shadowBlur=0;ctx.fillStyle='rgba(255,255,255,.55)';ctx.fillRect(-w/2+6,-h/2+3,w-12,2);\n    ctx.fillStyle='#12002b';ctx.font=\"italic 900 13px 'Arial Narrow','Nimbus Sans Narrow','Helvetica Neue',Arial,sans-serif\";ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(c.t,0,1);\n    ctx.restore();\n  }\n\n  drawPaddle();\n  drawBalls();\n\n  // particles\n  ctx.globalCompositeOperation='lighter';\n  for(const p of parts){\n    if(!p.on)continue;\n    const a=clamp(p.life/p.max,0,1);\n    if(p.kind===1){ctx.globalAlpha=a*.8;ctx.strokeStyle=p.col;ctx.lineWidth=2;ctx.beginPath();const rr=p.w*(1.4-a)+4;ctx.ellipse(p.x,p.y,rr,rr*.45,0,0,Math.PI*2);ctx.stroke();continue;}\n    ctx.globalAlpha=a;ctx.fillStyle=p.col;\n    ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.r);ctx.fillRect(-p.w/2,-p.h/2,p.w,p.h);ctx.restore();\n  }\n  ctx.globalAlpha=1;\n\n  // pop text\n  ctx.globalCompositeOperation='source-over';\n  ctx.textAlign='center';ctx.textBaseline='middle';\n  for(const p of pops){\n    const t=p.t,a=t<.7?1:1-(t-.7)/.3,sc=t<.12?1.6-t/.12*.6:1;\n    ctx.globalAlpha=clamp(a,0,1);\n    ctx.font=`italic 900 ${Math.round(p.size*sc)}px 'Arial Narrow','Nimbus Sans Narrow','Helvetica Neue',Arial,sans-serif`;\n    ctx.shadowColor=p.col;ctx.shadowBlur=10;ctx.fillStyle='#fff';ctx.fillText(p.text,p.x,p.y-t*42);\n    ctx.shadowBlur=0;\n  }\n  ctx.globalAlpha=1;\n\n  // serve prompt\n  if(phase==='serve'&&ui==='game'){\n    const a=.55+.45*Math.sin(time*5);ctx.globalAlpha=a;ctx.fillStyle='#fff';ctx.shadowColor='#00f5d4';ctx.shadowBlur=10;\n    ctx.font=\"italic 800 17px 'Arial Narrow','Nimbus Sans Narrow','Helvetica Neue',Arial,sans-serif\";\n    ctx.fillText(matchMedia('(hover: none)').matches?'TAP TO LAUNCH':'CLICK · SPACE TO LAUNCH',FW/2,paddle.y-70);\n    ctx.shadowBlur=0;ctx.globalAlpha=1;\n  }\n  drawPowerBar();\n\n  // slow-mo tint and flashes\n  ctx.setTransform(1,0,0,1,0,0);\n  if(slowT>0){ctx.globalAlpha=Math.min(1,slowT)*.16;ctx.fillStyle='#9b5de5';ctx.fillRect(0,0,cv.width,cv.height);ctx.globalAlpha=1;}\n  if(flash>0){ctx.fillStyle=`rgba(${flashCol},${(flash*.55).toFixed(3)})`;ctx.fillRect(0,0,cv.width,cv.height);}\n}\nfunction drawGrid(){\n  const hz=FH*.6,vpX=FW/2,depth=FH-hz;\n  ctx.save();ctx.beginPath();ctx.rect(0,hz,FW,depth);ctx.clip();\n  ctx.lineWidth=1.2;\n  // horizontal lines rushing toward the player\n  for(let i=0;i<18;i++){\n    const z=(i+1-gridPhase);const y=hz+depth*(1.2/(z*0.55+.2))*.18;\n    if(y<hz||y>FH)continue;\n    const a=clamp((y-hz)/depth,0,1);\n    ctx.strokeStyle=`rgba(255,46,151,${(.15+a*.75).toFixed(3)})`;ctx.lineWidth=.8+a*1.6;\n    ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(FW,y);ctx.stroke();\n  }\n  // lines fanning from the vanishing point\n  ctx.lineWidth=1.2;\n  const gr=ctx.createLinearGradient(0,hz,0,FH);gr.addColorStop(0,'rgba(255,46,151,0)');gr.addColorStop(1,'rgba(255,46,151,.75)');\n  ctx.strokeStyle=gr;ctx.beginPath();\n  for(let i=-14;i<=14;i++){const xb=vpX+i*62;ctx.moveTo(vpX+i*4,hz);ctx.lineTo(xb*1.9-vpX*.9,FH+40);}\n  ctx.stroke();\n  ctx.restore();\n}\nfunction drawPaddle(){\n  const w=paddle.w*(1+paddle.sq*.22),h=PADDLE_H*(1-paddle.sq*.35),x=paddle.x-w/2,y=paddle.y-h/2+paddle.sq*3;\n  ctx.save();\n  ctx.shadowColor=laserT>0?'#ff2e97':'#00f5d4';ctx.shadowBlur=22;\n  const gr=ctx.createLinearGradient(0,y,0,y+h);gr.addColorStop(0,'#c9fff6');gr.addColorStop(.45,laserT>0?'#ff7ab8':'#00f5d4');gr.addColorStop(1,laserT>0?'#b0126a':'#008c9e');\n  ctx.fillStyle=gr;roundRect(ctx,x,y,w,h,h/2);ctx.fill();\n  ctx.shadowBlur=0;\n  ctx.fillStyle='rgba(255,255,255,.85)';roundRect(ctx,x+h*.6,y+2.5,w-h*1.2,2.4,1.2);ctx.fill();\n  // magenta end caps\n  ctx.fillStyle='#ff2e97';ctx.shadowColor='#ff2e97';ctx.shadowBlur=10;\n  roundRect(ctx,x,y,h*1.1,h,h/2);ctx.fill();roundRect(ctx,x+w-h*1.1,y,h*1.1,h,h/2);ctx.fill();\n  if(laserT>0){ctx.fillStyle='#fff';ctx.fillRect(x+6,y-5,3,6);ctx.fillRect(x+w-9,y-5,3,6);}\n  ctx.restore();\n  // reflection on the grid floor\n  ctx.globalAlpha=.18;ctx.fillStyle=laserT>0?'#ff2e97':'#00f5d4';roundRect(ctx,x+6,paddle.y+h/2+6,w-12,3,1.5);ctx.fill();ctx.globalAlpha=1;\n}\nfunction drawBalls(){\n  ctx.globalCompositeOperation='lighter';\n  const hot=combo>=8?'255,46,151':combo>=4?'255,158,0':'0,245,212';\n  for(const b of balls){\n    const t=b.trail,n=t.length/2;\n    ctx.lineCap='butt';ctx.strokeStyle=`rgb(${hot})`;\n    for(let i=1;i<n;i++){\n      const k=i/n;\n      ctx.globalAlpha=k*.22;ctx.lineWidth=BALL_R*2.6*k;\n      ctx.beginPath();ctx.moveTo(t[i*2-2],t[i*2-1]);ctx.lineTo(t[i*2],t[i*2+1]);ctx.stroke();\n      ctx.globalAlpha=k*.6;ctx.lineWidth=BALL_R*1.3*k;\n      ctx.beginPath();ctx.moveTo(t[i*2-2],t[i*2-1]);ctx.lineTo(t[i*2],t[i*2+1]);ctx.stroke();\n    }\n    ctx.globalAlpha=1;\n    const g=BALL_R*4.4;ctx.drawImage(ballSprite,b.x-g,b.y-g,g*2,g*2);\n  }\n  ctx.globalCompositeOperation='source-over';\n  for(const b of balls){ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(b.x,b.y,BALL_R*.82,0,Math.PI*2);ctx.fill();}\n}\nfunction drawPowerBar(){\n  const list=[];if(wideT>0)list.push(['W',wideT/14,'WIDE']);if(laserT>0)list.push(['L',laserT/10,'LASER']);if(slowT>0)list.push(['S',slowT/8,'SLOW-MO']);\n  let x=14;const y=FH-26;\n  ctx.font=\"italic 900 12px 'Arial Narrow','Nimbus Sans Narrow','Helvetica Neue',Arial,sans-serif\";ctx.textAlign='center';ctx.textBaseline='middle';\n  for(const [k,v,label] of list){\n    const col=POWERS[k].color,w=84;\n    ctx.fillStyle='rgba(255,255,255,.12)';roundRect(ctx,x,y-8,w,16,8);ctx.fill();\n    ctx.fillStyle=col;ctx.shadowColor=col;ctx.shadowBlur=8;roundRect(ctx,x,y-8,Math.max(16,w*v),16,8);ctx.fill();ctx.shadowBlur=0;\n    ctx.fillStyle='#fff';ctx.shadowColor='#12002b';ctx.shadowBlur=4;ctx.fillText(label,x+w/2,y+1);ctx.shadowBlur=0;\n    x+=w+10;\n  }\n}\n\n/* ============ main loop ============ */\nlet raf=0,last=performance.now(),acc=0;\nfunction frame(now){\n  raf=requestAnimationFrame(frame);\n  let dt=(now-last)/1000;last=now;if(dt>.05)dt=.05;\n  update(dt);render();\n  if(ui==='game'||ui==='title')hud();\n  syncLegend();\n}\nfunction start(){if(!raf){last=performance.now();raf=requestAnimationFrame(frame);}}\nfunction stop(){cancelAnimationFrame(raf);raf=0;}\ndocument.addEventListener('visibilitychange',()=>{if(document.hidden){if(ui==='game')pause();stop();}else start();});\n\nlet rT=0;\nwindow.addEventListener('resize',()=>{clearTimeout(rT);rT=setTimeout(()=>{layout();render();},90);});\n\n/* ============ boot ============ */\nlayout();\ntoTitle();\nhud(true);\nstart();\n})();\n</script>\n</body>\n</html>\n";
